# MutableMapping does not provide the union operators and dict only supports them with other dicts,
# so implement them here to allow combining with any mapping (see combine_vars)
def __or__(self, other):
    if isinstance(other, MutableMapping):
        c = self.copy()
        c.update(other)
        return c
    return NotImplemented

def __ror__(self, other):
    if isinstance(other, MutableMapping):
        c = dict(other)
        c.update(self.data)
        return c
    return NotImplemented

def __ior__(self, other):
    self.data.update(other)
    return self

